DELETE FROM match_participants
WHERE match_id IN (
    '10000000-0000-4000-8000-000000000001',
    '10000000-0000-4000-8000-000000000002',
    '10000000-0000-4000-8000-000000000003',
    '10000000-0000-4000-8000-000000000004',
    '10000000-0000-4000-8000-000000000005',
    '10000000-0000-4000-8000-000000000006',
    '10000000-0000-4000-8000-000000000007',
    '10000000-0000-4000-8000-000000000008',
    '10000000-0000-4000-8000-000000000009',
    '10000000-0000-4000-8000-000000000010'
);

DELETE FROM medals
WHERE event_id BETWEEN 1 AND 10
  AND athlete_id BETWEEN
      '00000000-0000-4000-8000-000000000001'::UUID
      AND '00000000-0000-4000-8000-000000000010'::UUID;

DELETE FROM matches
WHERE id BETWEEN
    '10000000-0000-4000-8000-000000000001'::UUID
    AND '10000000-0000-4000-8000-000000000010'::UUID;

DELETE FROM athletes
WHERE id BETWEEN
    '00000000-0000-4000-8000-000000000001'::UUID
    AND '00000000-0000-4000-8000-000000000010'::UUID;

DELETE FROM sport_events
WHERE id BETWEEN 1 AND 10
  AND name LIKE '% Contoh';

DELETE FROM venues
WHERE id BETWEEN 6 AND 10
  AND name LIKE '% Contoh';
